{
  "interpretation": {
    "name": "Line2NutrunnerTighteningAndReturn",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Bring nutrunner NR7 from the crib to station st2, tighten the F30 fasteners per the MES program, evaluate and record the result, and return the tool to the crib.",
    "constraints": [
      "NR7 must be reserved before any use and released after it is back in the crib",
      "transport-tool must be executed by agvexecutor",
      "The tool must be at st2 before configure-tool and tighten-fasteners",
      "The tightening program must come only from get-program, with no numeric literals in the Recipe",
      "The tightening must be evaluated and recorded (quality policy)",
      "Every tool-using Step renews the lease and therefore depends on reserve-tool"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "one-shot, immediate execution",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-nr7-tightening-and-return",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {"name": "reserve", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "program", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {"name": "transport-to-station", "service": "transport-tool", "next": [], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "tighten",
        "next": "evaluate-and-return",
        "steps": [
          {"name": "configure", "service": "configure-tool", "next": ["tighten-bolts"], "dep": ["program", "reserve"], "executor": null, "params": {}},
          {"name": "tighten-bolts", "service": "tighten-fasteners", "next": [], "dep": ["configure", "reserve"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "evaluate-and-return",
        "next": "release",
        "steps": [
          {"name": "evaluate", "service": "evaluate-tightening", "next": [], "dep": ["tighten-bolts", "program"], "executor": null, "params": {}},
          {"name": "record", "service": "record-tightening", "next": [], "dep": ["tighten-bolts"], "executor": null, "params": {}},
          {"name": "transport-to-crib", "service": "transport-tool", "next": [], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "crib"}}
        ]
      },
      {
        "name": "release",
        "next": null,
        "steps": [
          {"name": "release-nr7", "service": "release-tool", "next": [], "dep": ["reserve"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
